pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetMinSum(0);
        c.Initialized();
    }
    function testFuzz_property(uint96 depositAmount, uint96 collectAmount, address sender, address other) public {
        // Bound parameters to avoid overflow and keep collect feasible
        vm.assume(sender != other);
        depositAmount = uint96(bound(depositAmount, 1, type(uint96).max));
        collectAmount = uint96(bound(collectAmount, 1, depositAmount));

        // fund sender and deposit
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // record state before collect
        uint256 senderBalBefore = c.balances(sender);
        uint256 contractBalBefore = address(c).balance;

        // collect
        vm.prank(sender);
        c.Collect(collectAmount);

        // after collect: invariant is that total Ether (sender balance in contract + contract balance) 
        // should equal total Ether before collect, because no other Ether has moved.
        // The contract's entire Ether balance is exactly the sum of all correctly recorded balances,
        // which is true for the reference but not for the mutant (mutant records double deposit but Ether is single).
        uint256 senderBalAfter = c.balances(sender);
        uint256 contractBalAfter = address(c).balance;

        // For the reference, senderBalAfter equals senderBalBefore - collectAmount,
        // and contractBalAfter equals contractBalBefore - collectAmount.
        // So senderBalAfter + contractBalAfter == senderBalBefore + contractBalBefore - 2*collectAmount? Wait, no.
        // Actually the correct invariant is simple: the sum of all recorded balances equals the contract's Ether balance.
        // We can check that after collect, the sum over the two known accounts (sender and other) equals the Ether balance,
        // because no other accounts have balances (other's balance is zero).
        uint256 totalRecorded = c.balances(sender) + c.balances(other);
        assertEq(totalRecorded, address(c).balance);
    }
}

