import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint96 depositAmount, uint96 collectAmount, address depositor, address collector) public {
        // Ensure nonzero deposits and safe collect amounts
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(depositor != address(0) && collector != address(0));
        vm.assume(depositor != collector);

        // Initialize contract
        c.Initialized();
        c.SetMinSum(0);

        // Deploy a benign log destination (needed by Deposit)
        LogFile lf = new LogFile();
        c.SetLogFile(address(lf));

        // --- Deposits ---
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        vm.deal(collector, depositAmount);
        vm.prank(collector);
        c.Deposit{value: depositAmount}();

        // Record balances and contract Ether before collect
        uint balDepositorBefore = c.balances(depositor);
        uint balCollectorBefore = c.balances(collector);
        uint balOthersBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        uint sumBalBefore = balDepositorBefore + balCollectorBefore + balOthersBefore;
        uint sumEthAndBalBefore = ethBefore + sumBalBefore;

        // --- Collect by collector (collector may try to collect up to its balance) ---
        uint toCollect = bound(collectAmount, 1, balCollectorBefore);
        vm.prank(collector);
        try c.Collect(toCollect) {} catch {}

        // Record balances and contract Ether after collect
        uint balDepositorAfter = c.balances(depositor);
        uint balCollectorAfter = c.balances(collector);
        uint balOthersAfter = c.balances(address(this));
        uint ethAfter = address(c).balance;
        uint sumBalAfter = balDepositorAfter + balCollectorAfter + balOthersAfter;
        uint sumEthAndBalAfter = ethAfter + sumBalAfter;

        // Invariant: Ether + sum of all tracked balances remains constant (no ether created/destroyed)
        assertEq(sumEthAndBalAfter, sumEthAndBalBefore, "Conservation broken: Ether + sum(balances) changed");
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
