contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); c.Initialized(); }

    function testFuzz_property(uint96 depositVal, uint96 collectAm, address sender, address other) public {
        // Bind msg.value to a safe range that avoids overflow but allows wide variation
        uint256 dVal = uint256(depositVal);
        uint256 cAm = uint256(collectAm);

        // Restrict ether amounts to a realistic domain that does not overflow uint96 but remains wide
        vm.assume(dVal > 0);
        vm.assume(cAm <= dVal);
        vm.assume(dVal <= type(uint96).max);
        vm.assume(cAm <= type(uint96).max);
        vm.assume(sender != address(0) && sender != address(c) && sender != address(this));
        vm.assume(other != sender && other != address(c) && other != address(this) && other != address(0));

        // Record balance of sender before deposit
        uint256 balBefore = c.balances(sender);
        // Deposit
        vm.deal(sender, dVal);
        vm.prank(sender);
        c.Deposit{value: dVal}();

        uint256 balAfterDeposit = c.balances(sender);
        // Ensure deposit succeeded and balance increased
        require(balAfterDeposit == balBefore + dVal, "deposit invariant broken in P");

        // Now Collect the specified amount (sender sends no ether, Collect is not payable)
        vm.prank(sender);
        c.Collect(cAm);

