pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount, uint256 initBalance) public {
        // 1. Admissible domain: exclude zero address (practical), and bound initBalance to avoid
        //    making the reference revert for reasons other than the overflow check.
        vm.assume(caller != address(0));
        // Bound initBalance away from type(uint256).max so reference overflow check
        // always passes; keep it wide – up to type(uint256).max - 10**30.
        bound(initBalance, 0, type(uint256).max - 10**30);
        amount = bound(amount, 1, type(uint256).max - initBalance); // ensure reference does not overflow

        // 2. Set up the caller's initial balance and provide Ether for the deposit.
        vm.deal(caller, amount);
        // We simulate a previous balance by directly manipulating the mapping if there was
        // a setter, but balances has no setter; we use the fact that Deposit adds to balance.
        // To set initBalance, we perform a deposit from the caller first.
        if (initBalance > 0) {
            // Fund the initial deposit
            vm.deal(caller, initBalance + amount);
            vm.prank(caller);
            c.Deposit{value: initBalance}();
        }

        // 3. Drive the Deposit entry point.
        bool success;
        uint256 balanceBefore = c.balances(caller);
        vm.prank(caller);
        try c.Deposit{value: amount}() {
            success = true;
        } catch {
            success = false;
        }

        uint256 balanceAfter = c.balances(caller);

        // 4. Assertion: if Deposit succeeded, the new balance must be at least the deposited amount.
        // For the reference, this always holds (addition without overflow).
        // For the buggy mutant, overflow can wrap the balance to a value less than amount.
        assertTrue(!success || balanceAfter >= amount);
    }
}

